    'faq_a17' => '<p><b>A.</b> जब तक अन्यथा न कहा जाए, सभी समय सिडनी ऑस्ट्रेलिया के अनुरूप यूटीसी+10 (UTC+10) समय क्षेत्र में दिखाए जाते हैं। बुकिंग करते समय कृपया अपने समय क्षेत्र सेटिंग्स की पुष्टि करें।</p>',
    'faq_q18' => '<h3>Q18. क्या मुझे पाठ्यक्रम पूरा करने के बाद प्रमाण पत्र मिलेगा?</h3>',
    'faq_a18' => '<p><b>A.</b> हाँ। जो छात्र सभी असाइनमेंट सबमिट करते हैं और 80% या अधिक का अंतिम स्कोर प्राप्त करते हैं, उन्हें पाठ्यक्रम पूरा होने पर एक डिजिटल प्रमाण पत्र प्राप्त होगा।</p>',
    'faq_q19' => '<h3>Q19. यदि मैं और सुधार करना चाहूँ तो क्या मैं वही पाठ्यक्रम दोबारा ले सकता हूँ?</h3>',
    'faq_a19' => '<p><b>A.</b> हाँ। कुछ छात्र अधिक आत्मविश्वास हासिल करने या एक विशिष्ट सीईएफआर स्तर को मजबूत करने के लिए पाठ्यक्रम दोबारा लेते हैं। हम अगले पाठ्यक्रम के लिए पंजीकरण करने या यह मूल्यांकन करने में भी आपकी सहायता कर सकते हैं कि क्या आप अगले स्तर के लिए तैयार हैं।</p>',
    'faq_q20' => '<h3>Q20. क्या होगा यदि मुझे किसी पाठ या असाइनमेंट का कोई हिस्सा समझ में न आए?</h3>',
    'faq_a20' => '<p><b>A.</b> चिंता न करें! आप आमने-सामने के लाइव सत्र के दौरान अपने शिक्षक से पूछ सकते हैं या ईमेल द्वारा हमारी सहायता टीम से संपर्क कर सकते हैं। हम आपकी सफलता सुनिश्चित करने के लिए यहाँ हैं।</p>',
    'about_title' => '<h1>हमारे बारे में</h1>',
    'about_h1' => '<h1>@School में आपका स्वागत है — आत्मविश्वासी अंग्रेजी का आपका मार्ग</h1>',
    'about_p1' => '<p>@School में, हमारा मानना है कि सही मार्गदर्शन, प्रोत्साहन और उपकरणों के साथ कोई भी अंग्रेजी सीख सकता है। हमारा मिशन सरल है: आपको इस तरह से अंग्रेजी बोलने, समझने और उसका आनंद लेने में मदद करना जो प्राकृतिक, उपयोगी और सुखद लगे।</p>',
    'about_h2' => '<h2>हम किसकी मदद करते हैं</h2>',
    'about_p2' => '<p>हम वयस्क शिक्षार्थियों — विशेष रूप से जापानी और स्पेनिश भाषियों — को उनकी अंग्रेजी सीखने की यात्रा के किसी भी चरण में मदद करने में विशेषज्ञ हैं। चाहे आप बिल्कुल शुरुआती हों, लंबे ब्रेक के बाद वापस लौट रहे हों, या उन्नत कौशल को परिष्कृत करना चाहते हों, हम आपकी चुनौतियों को समझते हैं: आत्मविश्वास की कमी, सीमित समय, या अगले कदम के बारे में अनिश्चितता। इसीलिए हमने @School को व्यावहारिक, सहायक और लचीला बनाने के लिए डिज़ाइन किया है, जिससे आपको अपने पेस पर आत्मविश्वास के साथ प्रगति करने में मदद मिलती है।</p>',
    'about_h3' => '<h2>क्या हमें अलग बनाता है</h2>',
    'about_p3' => '<p>हमारा दृष्टिकोण प्रौद्योगिकी और मानवीय संपर्क के सर्वोत्तम पहलुओं को जोड़ता है:</p>',
    'about_ul1' => '<ul><li>मूल अंग्रेजी बोलने वाले शिक्षकों के साथ लाइव पाठ जो व्यक्तिगत मार्गदर्शन प्रदान करते हैं।</li><li>एआई चैटबॉट अभ्यास किसी भी समय उपलब्ध है, ताकि आप बिना किसी डर या दबाव के कौशल का निर्माण कर सकें।</li><li>स्पष्ट साप्ताहिक पाठ योजनाएं जो आपको ट्रैक पर और प्रेरित रखती हैं।</li><li>आपकी मातृभाषा में सहायता ताकि आप कभी भी भ्रमित या असहाय महसूस न करें।</li></ul>',
    'about_h4' => '<h2>हमारी कहानी</h2>',
    'about_p4' => '<p>@School को अंग्रेजी सीखने को कम डरावना और अधिक सुलभ बनाने के लिए बनाया गया था। हमने देखा कि कितने लोग सीखना चाहते थे लेकिन पारंपरिक कक्षाओं में घबराहट महसूस करते थे, या स्व-अध्ययन ऐप्स में खो जाते थे। इसलिए, हमने एक ऐसा कार्यक्रम बनाया जो सुविधा, संरचना और प्रोत्साहन का मिश्रण है — चाहे आप दुनिया में कहीं भी हों।</p>',
    'about_h5' => '<h2>आपका सीखने का अनुभव</h2>',
    'about_p5' => '<p>प्रत्येक @School पाठ्यक्रम निर्देशित प्रगति का 6 सप्ताह का कार्यक्रम है:</p>',
    'about_ul2' => '<ul><li>साप्ताहिक असाइनमेंट</li><li>आपके शिक्षक के साथ प्रति सप्ताह दो 30-मिनट के लाइव पाठ</li><li>आपको बेहतर बनाए रखने के लिए निरंतर प्रतिक्रिया और सुधार</li><li>एक लचीला शेड्यूल जिसे आप अपने जीवन के अनुसार पूरी तरह ढाल सकते हैं</li></ul>',
    'about_h6' => '<h2>हमारे मूल्य</h2>',
    'about_ul3' => '<ul><li>सभी शिक्षार्थियों के लिए सुलभता</li><li>सफर के हर कदम पर निरंतर प्रोत्साहन</li><li>सांस्कृतिक पृष्ठभूमि के लिए गहरा सम्मान</li><li>व्यावहारिक, वास्तविक दुनिया के अंग्रेजी कौशल</li></ul>',
    'about_h7' => '<h2>हमारे साथ जुड़ें</h2>',
    'about_p7' => '<p>चाहे आप यात्रा, काम या व्यक्तिगत विकास के लिए सीख रहे हों, @School आपको सफल होने के लिए कौशल और आत्मविश्वास प्रदान करता है। हम यहाँ आपका मार्गदर्शन करने के लिए हैं — एक समय में एक बातचीत के माध्यम से।</p>',
    'compare_title' => '<h2>@School पाठ्यक्रम के प्रकार — तुलनात्मक विवरण</h2>',
