    'compare_table8' => '<tr><th scope="row">इमर्शन (तल्लीनता) गतिविधियाँ</th><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td></tr>',
    'compare_table9' => '<tr><th scope="row">शिक्षक के साथ ईमेल गतिविधियाँ</th><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td></tr>',
    'compare_table10' => '<tr><th scope="row">लाइव शिक्षक सत्र</th><td style="font-size:1.2em">—</td><td>प्रति सप्ताह 2 × 30-मिनट के सत्र</td><td>प्रति सप्ताह 2 × 60-मिनट के सत्र</td></tr>',
    'compare_table11' => '<tr><th scope="row">शिक्षक के साथ ऑफिस ऑवर्स</th><td>15 मिनट<br>सप्ताह में 2×</td><td>15 मिनट<br>सप्ताह में 3×</td><td>15 मिनट<br>सप्ताह में 4×</td></tr>',
    'compare_table12' => '<tr><th scope="row">पाठ्यक्रम की गति</th><td>स्व-गति से (Self-paced)</td><td>मानक गति</td><td>नियमित से 2 गुना तेज गति</td></tr>',
    'compare_table13' => '<tr><th scope="row">शिक्षक प्रतिक्रिया की गहराई</th><td>सीमित (एसिंक्रोनस)</td><td>निर्देशित और संवादात्मक</td><td>अत्यधिक व्यक्तिगत और गहन सुधार</td></tr>',
    'compare_table14' => '<tr><th scope="row">इसके लिए सबसे अच्छा है</th><td>स्व-प्रेरित शिक्षार्थी</td><td>संतुलित अध्ययन + बोलने का अभ्यास</td><td>तेजी से प्रगति और उच्च तल्लीनता</td></tr>',
    'compare_courseblurb_main' => '<h3>पाठ्यक्रम विवरण</h3>',
    'compare_courseblurb_title1' => '<h4>स्वतंत्र अध्ययन</h4>',
    'compare_courseblurb_p1' => '<p>प्रेरित शिक्षार्थियों के लिए एक लचीला, स्व-गति वाला विकल्प जो सीमित शिक्षक सहायता के साथ संरचित सामग्री चाहते हैं। व्यस्त पेशेवरों या समीक्षा-केंद्रित अध्ययन के लिए आदर्श।</p>',
    'compare_courseblurb_title2' => '<h4>नियमित पाठ्यक्रम</h4>',
    'compare_courseblurb_p2' => '<p>एक संतुलित सीखने का अनुभव जो एक देशी-भाषी शिक्षक के नेतृत्व में लाइव साप्ताहिक सत्रों के साथ स्वतंत्र अध्ययन को जोड़ता है। निरंतर प्रगति और आत्मविश्वास निर्माण के लिए आदर्श।</p>',
    'compare_courseblurb_title3' => '<h4>गहन पाठ्यक्रम</h4>',
    'compare_courseblurb_p3' => '<p>लंबे शिक्षक सत्रों के साथ दोगुनी गति से समान सामग्री को कवर करने वाला एक तेज़ गति वाला, इमर्सिव कार्यक्रम। विशिष्ट लक्ष्यों या समय-संवेदनशील आवश्यकताओं वाले शिक्षार्थियों के लिए सर्वोत्तम।</p>',
    'welcome_email_subject' => '@School पोर्टल में आपका स्वागत है',
    'welcome_email_message' => "नमस्ते {first_name},\n\nआपका खाता सफलतापूर्वक बना दिया गया है।\n\nयहाँ आपकी लॉगिन जानकारी है:\nउपयोगकर्ता नाम: {username}\nपासवर्ड: {password}\n\nआप इस लिंक से लॉग इन कर सकते हैं:\n{login_url}\n\nकृपया पहली बार लॉग इन करने के बाद अपना पासवर्ड बदल दें।\n\nसादर,\n@School टीम",
    
